        srai  a0, a0, 1                 ; shift by 1
        li    a1, 0x91a2b3c4d5e6f7      ; a1 = expected: 0x91a2b3c4d5e6f7
        call  chk                       ; record a0, compare with a1
        li    a0, 0x123456789abcdef     ; a0 = source
        srai  a0, a0, 31                ; shift by 31
        li    a1, 0x2468acf             ; a1 = expected: 0x2468acf
        call  chk                       ; record a0, compare with a1
        li    a0, 0x123456789abcdef     ; a0 = source
        srai  a0, a0, 32                ; shift by 32
        li    a1, 0x1234567             ; a1 = expected: 0x1234567
        call  chk                       ; record a0, compare with a1
        li    a0, 0x123456789abcdef     ; a0 = source
        srai  a0, a0, 63                ; shift by 63
        li    a1, 0x0                   ; a1 = expected: 0x0
        call  chk                       ; record a0, compare with a1
; ---- lui: imm16 << 16, sign-extended from bit 31
        lui   a0, 0x0                   ; a0 = sext(0x0) << 16
        li    a1, 0x0                   ; a1 = expected: 0x0
        call  chk                       ; record a0, compare with a1
        lui   a0, 0x1                   ; a0 = sext(0x1) << 16
        li    a1, 0x10000               ; a1 = expected: 0x10000
        call  chk                       ; record a0, compare with a1
        lui   a0, 0x7fff                ; a0 = sext(0x7fff) << 16
        li    a1, 0x7fff0000            ; a1 = expected: 0x7fff0000
        call  chk                       ; record a0, compare with a1
        lui   a0, 0x8000                ; a0 = sext(0x8000) << 16
        li    a1, 0xffffffff80000000    ; a1 = expected: 0xffffffff80000000
        call  chk                       ; record a0, compare with a1
        lui   a0, 0xffff                ; a0 = sext(0xffff) << 16
        li    a1, 0xffffffffffff0000    ; a1 = expected: 0xffffffffffff0000
        call  chk                       ; record a0, compare with a1
        lui   a0, 0x1234                ; a0 = sext(0x1234) << 16
        li    a1, 0x12340000            ; a1 = expected: 0x12340000
        call  chk                       ; record a0, compare with a1
; ---- encodings with nonzero funct bits 4..10 are illegal
alu_ill0:
        .word 0x01400010                ; ALU opcode, rd = a0, funct = 0x10: illegal
        li    a0, C_ILLEGAL             ; expected cause
        la    a1, alu_ill0              ; expected epc: the instruction itself
        li    a2, 0x1400010             ; expected tval: the instruction word
        call  chkt                      ; check the recorded trap
alu_ill1:
        .word 0x01400402                ; ALU opcode, rd = a0, funct = 0x402: illegal
        li    a0, C_ILLEGAL             ; expected cause
        la    a1, alu_ill1              ; expected epc: the instruction itself
        li    a2, 0x1400402             ; expected tval: the instruction word
        call  chkt                      ; check the recorded trap
        j     done                      ; print the signature and the verdict
